package glitch

import data.glitch_lib

conditional_has_default(cond) {
    walk(cond, [_, branch])
    branch.ir_type == "ConditionalStatement"
    branch.is_default == true
}

is_switch_type(cond) {
    cond.type == 2
}

is_switch_type(cond) {
    cond.type == "SWITCH"
}

is_if_type(cond) {
    cond.type == 1
}

is_if_type(cond) {
    cond.type == "IF"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conds := glitch_lib.all_conditional_statements(parent)
    cond := conds[_]
    cond.is_top == true
    is_switch_type(cond)
    not conditional_has_default(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in switch/multi-condition expression - All switch expressions should include a default/fallback case. (CWE-478)"
    }
}

